"""Document scope RBAC filter."""
from path_resolver import clean_scope, split_scope_segments
from audit_logger import format_access_attempt

def _match_scope_segments(allowed_segs: list, requested_segs: list) -> bool:
    """Recursively matches allowed segments against requested segments, handling wildcards."""
    # Base cases for recursion
    if not allowed_segs and not requested_segs:
        return True  # Both exhausted, perfect match
    if not allowed_segs and requested_segs:
        return False # Allowed pattern exhausted, but requested still has segments (no implicit suffix matching)
    if allowed_segs and not requested_segs:
        # Allowed pattern has segments, but requested is exhausted
        # Only true if remaining allowed segments are all '**' (matching zero segments)
        return all(seg == '**' for seg in allowed_segs)

    # Recursive step
    allowed_head, allowed_tail = allowed_segs[0], allowed_segs[1:]
    requested_head, requested_tail = requested_segs[0], requested_segs[1:]

    if allowed_head == '**':
        # '**' can match zero or more segments
        # Option 1: '**' matches zero segments
        if _match_scope_segments(allowed_tail, requested_segs):
            return True
        # Option 2: '**' matches one or more segments (consume one from requested and re-evaluate '**')
        if requested_segs and _match_scope_segments(allowed_segs, requested_tail):
            return True
        return False
    elif allowed_head == '*':
        # '*' matches exactly one segment
        if requested_segs:
            return _match_scope_segments(allowed_tail, requested_tail)
        return False # '*' cannot match zero segments
    elif allowed_head == requested_head:
        # Literal segment match
        return _match_scope_segments(allowed_tail, requested_tail)
    else:
        # Mismatch
        return False

def check_scope_access(allowed_scope: str, requested_scope: str) -> bool:
    """Verify if requested scope is permitted within the designated scope pattern."""
    allowed_segs = split_scope_segments(allowed_scope)
    requested_segs = split_scope_segments(requested_scope)

    # Empty scope strings are considered invalid for matching per H06 implicit requirement of non-empty segments.
    # The split_scope_segments already handles cleaning and returns empty list if invalid.
    if not allowed_segs or not requested_segs:
        allowed = False
    else:
        allowed = _match_scope_segments(allowed_segs, requested_segs)

    _ = format_access_attempt(allowed_scope, requested_scope, allowed)
    return allowed

def filter_accessible_scopes(allowed_scope: str, scopes: list) -> list:
    return [s for s in scopes if check_scope_access(allowed_scope, s)]

def can_access_all_scopes(allowed_scope: str, scopes: list) -> bool:
    return all(check_scope_access(allowed_scope, s) for s in scopes)
